css:
.rm-t-serif-editorial{padding:58px 64px 52px;background:#fffdf9;color:#3c352d;font-size:13.2px;line-height:1.72;font-family:Georgia,"Songti SC","Noto Serif SC","SimSun",serif;}
.rm-t-serif-editorial .rm-head{margin:0;padding:0 0 22px;background:transparent;border-bottom:3px double #d9cfc0;}
.rm-t-serif-editorial .rm-name{margin:0;font-size:43px;line-height:1.16;font-weight:600;letter-spacing:.08em;color:#2f2a24;}
.rm-t-serif-editorial .rm-role{margin:10px 0 0;font-size:11.5px;letter-spacing:.32em;color:#8a6a4f;}
.rm-t-serif-editorial .rm-contact{grid-template-columns:repeat(2,minmax(0,1fr));gap:6px 34px;margin:18px 0 0;max-width:566px;}
.rm-t-serif-editorial .rm-k{font-size:9px;letter-spacing:.24em;color:#a3947f;text-transform:uppercase;}
.rm-t-serif-editorial .rm-v{font-size:12px;color:#4a4238;}
.rm-t-serif-editorial .rm-photo{width:104px;height:104px;background:#f7f2ea;border:1px solid #d9cfc0;}
.rm-t-serif-editorial .rm-sec{margin-top:26px;}
.rm-t-serif-editorial .rm-sec-h{margin:0 0 13px;padding:6px 0 5px;border-top:1px solid #dcd3c4;border-bottom:1px solid #dcd3c4;}
.rm-t-serif-editorial .rm-sec-t{font-size:12px;font-weight:600;letter-spacing:.3em;color:#5b4a38;}
.rm-t-serif-editorial .rm-summary{margin:0;font-size:13.4px;line-height:1.8;color:#3c352d;}
.rm-t-serif-editorial .rm-summary::first-letter{float:left;margin:7px 10px 0 0;font-size:44px;line-height:.84;font-weight:600;color:#8a6a4f;}
.rm-t-serif-editorial .rm-item{margin:0 0 12px;}
.rm-t-serif-editorial .rm-item-t{font-weight:600;letter-spacing:.02em;color:#2f2a24;}
.rm-t-serif-editorial .rm-item-role{margin-left:7px;font-size:12px;font-style:italic;color:#7a6a58;}
.rm-t-serif-editorial .rm-date{font-size:11px;color:#8d7f6c;font-variant-numeric:tabular-nums;}
.rm-t-serif-editorial .rm-item-sub{margin-top:2px;font-size:11.5px;font-style:italic;color:#7a6a58;}
.rm-t-serif-editorial .rm-bullets{margin:5px 0 0;padding-left:16px;}
.rm-t-serif-editorial .rm-bullets li{margin:3px 0;color:#3c352d;}
.rm-t-serif-editorial .rm-bullets li::marker{color:#c0a888;}
.rm-t-serif-editorial .rm-body{padding:0;}
.rm-t-serif-editorial .rm-sec-campus .rm-item-role{font-style:italic;}
.rm-t-serif-editorial .rm-sec-hobbies .rm-tags{gap:8px;}
.rm-t-serif-editorial .rm-edu-courses{margin-top:3px;font-size:11.5px;color:#7a6a58;}
.rm-t-serif-editorial .rm-edu-courses .rm-k{margin-right:7px;color:#a3947f;}
.rm-t-serif-editorial .rm-skill-row{grid-template-columns:100px minmax(0,1fr);gap:10px;margin:0 0 7px;}
.rm-t-serif-editorial .rm-skill-k{font-size:12px;font-style:italic;color:#8a6a4f;}
.rm-t-serif-editorial .rm-tags{gap:3px 14px;}
.rm-t-serif-editorial .rm-tag{padding:0 0 1px;border:0;border-bottom:1px solid #cfc2ae;border-radius:0;background:transparent;color:#4a4238;font-size:11.5px;line-height:1.7;}
.rm-t-serif-editorial .rm-award-row{margin:0 0 7px;align-items:baseline;}
.rm-t-serif-editorial .rm-award-t{font-weight:600;color:#2f2a24;}
.rm-t-serif-editorial .rm-award-desc{font-size:11.5px;font-style:italic;color:#7a6a58;}
.rm-t-serif-editorial strong{color:#2f2a24;font-weight:650;}
